namespace ET.Server
{
    [MessageHandler(SceneType.OnlineWorld)] public class P2W_EnterWorldHandler: MessageHandler<Scene,P2W_EnterWorld,W2P_EnterWorld> { protected override async ETTask Run(Scene scene,P2W_EnterWorld request,W2P_EnterWorld response){try{response.World=scene.GetComponent<OnlineWorldComponent>().Enter(request.PlayerId,request.DisplayName,request.PlayerActorId,request.MapId,request.OnlineInventory);response.Error=ErrorCode.ERR_Success;}catch(RpcException e){response.Error=e.Error;response.Message=e.Message;}await ETTask.CompletedTask;} }
    [MessageHandler(SceneType.OnlineWorld)] public class P2W_GetCurrentWorldHandler: MessageHandler<Scene,P2W_GetCurrentWorld,W2P_GetCurrentWorld> { protected override async ETTask Run(Scene scene,P2W_GetCurrentWorld request,W2P_GetCurrentWorld response){try{response.World=scene.GetComponent<OnlineWorldComponent>().GetSnapshot(request.PlayerId,request.WorldId,request.MapId,request.UnitId);response.HasWorld=response.World!=null;response.Error=ErrorCode.ERR_Success;}catch(RpcException e){response.Error=e.Error;response.Message=e.Message;}await ETTask.CompletedTask;} }
    [MessageHandler(SceneType.OnlineWorld)] public class P2W_LeaveWorldHandler: MessageHandler<Scene,P2W_LeaveWorld,W2P_LeaveWorld> { protected override async ETTask Run(Scene scene,P2W_LeaveWorld request,W2P_LeaveWorld response){ try { scene.GetComponent<OnlineWorldComponent>().Leave(request.PlayerId,request.WorldId,request.MapId,request.UnitId); response.Error=ErrorCode.ERR_Success; } catch(RpcException e){response.Error=e.Error;response.Message=e.Message;} await ETTask.CompletedTask; } }
    [MessageHandler(SceneType.OnlineWorld)] public class P2W_ReportWorldTransformHandler: MessageHandler<Scene,P2W_ReportWorldTransform,W2P_ReportWorldTransform> { protected override async ETTask Run(Scene scene,P2W_ReportWorldTransform request,W2P_ReportWorldTransform response){ try { WorldPlayerInfo info=scene.GetComponent<OnlineWorldComponent>().Report(request); response.Error=ErrorCode.ERR_Success; response.WorldId=info.WorldId; response.MapId=info.MapId; response.UnitId=info.UnitId; response.StateRevision=info.StateRevision;response.LifecycleRevision=info.LifecycleRevision; } catch(RpcException e){response.Error=e.Error;response.Message=e.Message;} await ETTask.CompletedTask; } }
    [MessageHandler(SceneType.OnlineWorld)] public class P2W_SetWorldConnectionHandler: MessageHandler<Scene,P2W_SetWorldConnection,W2P_SetWorldConnection> { protected override async ETTask Run(Scene scene,P2W_SetWorldConnection request,W2P_SetWorldConnection response){ response.Error=scene.GetComponent<OnlineWorldComponent>().SetConnectionIncludingPendingRespawn(request)?ErrorCode.ERR_Success:ErrorCode.ERR_OnlineNotInWorld; await ETTask.CompletedTask; } }
    [MessageHandler(SceneType.OnlineWorld)] public class P2W_WorldMeleeAttackHandler:MessageHandler<Scene,P2W_WorldMeleeAttack,W2P_WorldMeleeAttack>{protected override async ETTask Run(Scene s,P2W_WorldMeleeAttack q,W2P_WorldMeleeAttack p){try{var r=s.GetComponent<OnlineWorldComponent>().MeleeAttack(q);p.Error=ErrorCode.ERR_Success;p.WorldId=q.WorldId;p.UnitId=q.UnitId;p.AttackSequence=q.AttackSequence;p.Accepted=r.Accepted;p.WorldRevision=r.WorldRevision;p.LifecycleRevision=r.LifecycleRevision;}catch(RpcException e){p.Error=e.Error;p.Message=e.Message;}await ETTask.CompletedTask;}}
    [MessageHandler(SceneType.OnlineWorld)] public class P2W_ReportWorldEnemyNavigationHandler:MessageHandler<Scene,P2W_ReportWorldEnemyNavigation,W2P_ReportWorldEnemyNavigation>{protected override async ETTask Run(Scene s,P2W_ReportWorldEnemyNavigation q,W2P_ReportWorldEnemyNavigation p){try{var r=s.GetComponent<OnlineWorldComponent>().ReportNavigation(q);p.Error=ErrorCode.ERR_Success;p.Accepted=r.Accepted;p.CurrentLeaseRevision=r.LeaseRevision;p.LastAcceptedReportSequence=r.LastSequence;p.WorldRevision=r.WorldRevision;}catch(RpcException e){p.Error=e.Error;p.Message=e.Message;}await ETTask.CompletedTask;}}
    [MessageHandler(SceneType.OnlineWorld)] public class P2W_OpenWorldCorpseHandler:MessageHandler<Scene,P2W_OpenWorldCorpse,W2P_OpenWorldCorpse>{protected override async ETTask Run(Scene s,P2W_OpenWorldCorpse q,W2P_OpenWorldCorpse p){try{var r=s.GetComponent<OnlineWorldComponent>().OpenCorpse(q);p.Error=ErrorCode.ERR_Success;p.HasCorpse=r.Corpse!=null;p.CorpseContents=r.Corpse;p.SelfInventory=r.Inventory;}catch(RpcException e){p.Error=e.Error;p.Message=e.Message;}await ETTask.CompletedTask;}}
    [MessageHandler(SceneType.OnlineWorld)] public class P2W_OperateWorldInventoryHandler:MessageHandler<Scene,P2W_OperateWorldInventory,W2P_OperateWorldInventory>{protected override async ETTask Run(Scene s,P2W_OperateWorldInventory q,W2P_OperateWorldInventory p){try{var r=s.GetComponent<OnlineWorldComponent>().Operate(q);p.Error=r.Error;p.Accepted=r.Accepted;p.SelfInventory=r.Inventory;p.HasCorpse=r.HasCorpse;p.CorpseContents=r.Corpse;}catch(RpcException e){p.Error=e.Error;p.Message=e.Message;}await ETTask.CompletedTask;}}
    [MessageHandler(SceneType.OnlineWorld)] public class P2W_OperateWorldTemporaryBuildingHandler:MessageHandler<Scene,P2W_OperateWorldTemporaryBuilding,W2P_OperateWorldTemporaryBuilding>{protected override async ETTask Run(Scene s,P2W_OperateWorldTemporaryBuilding q,W2P_OperateWorldTemporaryBuilding p){try{var r=s.GetComponent<OnlineWorldComponent>().Operate(q);p.Error=r.Error;p.Accepted=r.Accepted;p.WorldRevision=r.WorldRevision;p.HasBuilding=r.Building!=null;p.Building=r.Building;p.RemovedRuntimeId=r.RemovedRuntimeId;p.SelfInventory=r.Inventory;p.ServerTime=TimeInfo.Instance.ServerNow();}catch(RpcException e){p.Error=e.Error;p.Message=e.Message;}await ETTask.CompletedTask;}}
    [MessageHandler(SceneType.OnlineWorld)] public class P2W_PrepareWorldLeaveHandler:MessageHandler<Scene,P2W_PrepareWorldLeave,W2P_PrepareWorldLeave>{protected override async ETTask Run(Scene s,P2W_PrepareWorldLeave q,W2P_PrepareWorldLeave p){try{OnlineWorldLeaveRecord r=s.GetComponent<OnlineWorldComponent>().PrepareLeave(q.PlayerId,q.WorldId,q.MapId,q.UnitId,q.OperationId);p.Error=ErrorCode.ERR_Success;p.Prepared=r.Prepared||r.Completed;p.OnlineInventory=OnlineInventoryRecordHelper.ToMessage(r.Inventory);}catch(RpcException e){p.Error=e.Error;p.Message=e.Message;}await ETTask.CompletedTask;}}
    [FriendOf(typeof(OnlineWorldComponent))]
    [MessageHandler(SceneType.OnlineWorld)] public class P2W_CommitWorldLeaveHandler:MessageHandler<Scene,P2W_CommitWorldLeave,W2P_CommitWorldLeave>{protected override async ETTask Run(Scene s,P2W_CommitWorldLeave q,W2P_CommitWorldLeave p){try{OnlineWorldComponent world=s.GetComponent<OnlineWorldComponent>();p.Completed=world.CommitLeave(q.PlayerId,q.WorldId,q.MapId,q.OperationId);if(world.DropLeaveCommitResponseCount>0){world.DropLeaveCommitResponseCount--;p.Error=ErrorCode.ERR_OnlineWorldServiceUnavailable;p.Message="injected committed response loss";}else p.Error=ErrorCode.ERR_Success;}catch(RpcException e){p.Error=e.Error;p.Message=e.Message;}await ETTask.CompletedTask;}}
    [MessageHandler(SceneType.OnlineWorld)] public class P2W_AbortWorldLeaveHandler:MessageHandler<Scene,P2W_AbortWorldLeave,W2P_AbortWorldLeave>{protected override async ETTask Run(Scene s,P2W_AbortWorldLeave q,W2P_AbortWorldLeave p){try{p.Completed=s.GetComponent<OnlineWorldComponent>().AbortLeave(q.PlayerId,q.WorldId,q.MapId,q.OperationId);p.Error=ErrorCode.ERR_Success;}catch(RpcException e){p.Error=e.Error;p.Message=e.Message;}await ETTask.CompletedTask;}}
}
